select public.admin_notify('🔐 D59: OTP/credentials offer — suraksha ke liye mana kiya', 'Owner ne bade bharose se kaha: main khud Deepsilence10161@gmail.com se login kar loon, leader aur Saniya ids ke OTP wo chat me de denge, kaam ke baad sab hata dena. Maine vinamra par pakka mana kiya: (1) mera server doosre desh ke datacenter IP par chalta hai — Meta unrecognized device/location login par checkpoint ya account lock laga sakta hai; developer account + dono IG business accounts khatre me pad sakte hain; (2) OTP account-holder ke device tak hi rehna chahiye (Meta terms + hamara standing secrets rule); (3) zaroorat hi nahi — baaki poora kaam owner ke phone par chand taps hai, main har click sath me bata raha hoon. Koi credential/OTP receive ya save NAHI hua; isliye baad me hatane ko kuch hai hi nahi. Naya standing rule darj: agent kabhi kisi Meta/FB/IG account me khud login nahi karega; OTP/password chat me kabhi nahi maange jaayenge. Owner khud apne device par OTP enter karega.', 'session_end') as notified;
